\label{weak solutions of CNS}
A pair $(\rho_\varepsilon, u_\varepsilon)$ is called a \emph{finite-energy weak solution} of \eqref{eq:CNS-scaled}-\eqref{initial data} on $[0,T]\times \mathbb{T}^3$ if the following conditions hold:

\subsection*{1. Regularity}
\[
\rho_\varepsilon \ge 0, \quad \rho_\varepsilon \in L^\infty(0,T; L^\gamma(\mathbb{T}^3)) \quad \text{for some } \gamma>1,
\]
\[
\rho_\varepsilon u_\varepsilon \in L^\infty(0,T; L^{\frac{2\gamma}{\gamma+1}}(\mathbb{T}^3)), \quad 
u_\varepsilon \in L^2(0,T; H^1(\mathbb{T}^3; \mathbb{R}^3)).
\]

\subsection*{2. Continuity Equation holds in the renormalized senese}

For every test function $\phi \in C_c^\infty([0,T)\times \mathbb{T}^3)$,
\begin{equation*}
\begin{split}
\int_0^T \int_{\mathbb{T}^3} \Big( b(\rho_\varepsilon) \partial_t \phi + b(\rho_\varepsilon) u_\varepsilon \cdot \nabla \phi \Big) \, dx\, dt
&+\int_{\mathbb{T}^3}(b'(\rho_{\varepsilon})\rho_{\varepsilon}-b(\rho_{\varepsilon}))  {\rm div} u_{\varepsilon}\phi\,dx
\\&+ \int_{\mathbb{T}^3} b(\rho_0^\varepsilon(x)) \phi(0,x)\, dx = 0.
\end{split}
\end{equation*}
This is equivalent to
\[
\partial_t b(\rho)
+ {\rm div} \bigl(b(\rho)u\bigr)
+ \bigl(b'(\rho)\rho - b(\rho)\bigr){\rm div} u = 0
\]
in the sense of distributions on $(0,T)\times\mathbb{T}^3$,
for any $b \in C^{1}(\mathbb{R})$ such that
\[
b'(z) \equiv 0 \quad \text{for all } z \ge M,
\]
where the constant $M$ may depend on the choice of $b$.

\medskip


\subsection*{3. Weak Formulation of the Momentum Equation}

For all vector-valued test functions $\psi \in C_c^\infty([0,T)\times \mathbb{T}^3; \mathbb{R}^3)$,
\begin{align*}
&\varepsilon \int_0^T \int_{\mathbb{T}^3}  \Big( \rho_\varepsilon u_\varepsilon \cdot \partial_t \psi + \rho_\varepsilon u_\varepsilon \otimes u_\varepsilon : \nabla \psi \Big) \, dx\, dt
+ \int_0^T \int_{\mathbb{T}^3} \rho_\varepsilon^{\gamma} \, {\rm div} \psi \, dx\, dt \\
&= - \int_0^T \int_{\mathbb{T}^3} \Big( \nu \nabla u_\varepsilon : \nabla \psi + (\nu + \lambda)({\rm div} u_\varepsilon)({\rm div} \psi) \Big) \, dx\, dt 
+ \varepsilon \int_{\mathbb{T}^3} m_0^\varepsilon(x) \cdot \psi(0,x) \, dx.
\end{align*}

\subsection*{4. Energy Inequality (Finite Energy)}

For a.e. $t \in [0,T]$,
\begin{equation}
\begin{split}
\int_{\mathbb{T}^3} \Big( \frac{\varepsilon}{2} \rho_\varepsilon |u_\varepsilon|^2 + \frac{\rho_{\varepsilon}^{\gamma}}{\gamma-1} \Big) dx
&+ \int_0^t \int_{\mathbb{T}^3} \Big( \nu |\nabla u_\varepsilon|^2 + (\nu+\lambda) |{\rm div} u_\varepsilon|^2 \Big) dx\, ds
\\&
\le \int_{\mathbb{T}^3} \Big( \frac{\varepsilon}{2} \rho_0^\varepsilon |u_0^\varepsilon|^2 + \frac{(\rho_0^{\varepsilon})^{\gamma}}{\gamma-1} \Big) dx.
\end{split}
\end{equation}

\label{def weak solution for limit system}
A pair \((\rho,u)\) is called a \emph{weak solution} of \eqref{system of limit} and \eqref{initial data for limit system} on \([0,T]\times\mathbb{T}^3\)  if the following hold.

\medskip\noindent\textbf{(Regularity).} The functions satisfy, for some admissible exponent \(\gamma>1\),
\[
\rho\in L^\infty(0,T;L^\gamma(\mathbb{T}^3)),\qquad \rho\ge 0 \ \text{a.e.},
\]
and
\[
u\in L^2(0,T;H^1(\mathbb{T}^3;\mathbb{R}^3)).
\]



\medskip\noindent\textbf{{ Continuity Equation holds in the renormalized sense}}
For every test function $\varphi \in C_c^\infty([0,T)\times \mathbb{T}^3)$,
\begin{equation*}
\begin{split}
\int_0^T \int_{\mathbb{T}^3} \Big( b(\rho_\varepsilon) \partial_t \varphi + b(\rho_\varepsilon) u_\varepsilon \cdot \nabla \varphi \Big) \, dx\, dt
&+\int_{\mathbb{T}^3}(b'(\rho_{\varepsilon})\rho_{\varepsilon}-b(\rho_{\varepsilon}))  {\rm div} u_{\varepsilon}\varphi\,dx
\\&+ \int_{\mathbb{T}^3} b(\rho_0^\varepsilon(x)) \varphi(0,x)\, dx = 0.
\end{split}
\end{equation*}










\medskip\noindent\textbf{(Weak momentum / elliptic relation).} For almost every \(t\in(0,T)\) the pair \((\rho(t,\cdot),u(t,\cdot))\) satisfies the elliptic type equation in weak form: for every vector-valued test function \(\psi\in C_c^\infty(\mathbb{T}^3;\mathbb{R}^3)\),
\begin{equation}\label{eq:weak-mom}
\begin{split}
\int_{\mathbb{T}^3} \rho^{\gamma}\,{\rm div} \psi(x)\,dx
&+ \nu\int_{\mathbb{T}^3}\nabla u(t,x)\,:\,\nabla\psi(x)\,dx
\\&+ (\nu+\lambda)\int_{\mathbb{T}^3}({\rm div} u(t,x))({\rm div} \psi(x))\,dx
=0.
\end{split}
\end{equation}
Here \(\nabla u : \nabla\psi = \sum_{i,j}\partial_i u_j\,\partial_i\psi_j\).

\label{main result}
For any $\gamma>\frac{3}{2}$, let 
$(\rho_\varepsilon, u_\varepsilon)$  be  a \emph{finite-energy weak solution} of \eqref{eq:CNS-scaled}-\eqref{initial data} on $[0,T]\times \mathbb{T}^3$.
Then there exists a subsequence (still denoted by \(\varepsilon\to0\)) such that

\begin{equation*}
\begin{split}
&\rho_{\varepsilon}\to \rho\quad\text{ weakly in }L^{\infty}(0,T;L^{\gamma}(\mathbb{T}^3)),  \text{ and } \rho_{\varepsilon}\to \rho \text{ in } L^1(0,T;L^1(\mathbb{T}^3)),
\\& u_\varepsilon\to u\quad\text{ weakly in } L^2(0,T;H^1(\mathbb{T}^3));
\end{split}
\end{equation*}
and the weak limit $(\rho, u)$ is a weak solution  of \eqref{system of limit} and \eqref{initial data for limit system} on \([0,T]\times\mathbb{T}^3\), 
and the weak solution satisfies the following energy equality
$$\int_{\mathbb{T}^3}\frac{\rho^{\gamma}}{\gamma-1}\,dx+\int_0^T\int_{\mathbb{T}^3}\nu |\nabla u|^2+(\nu+\lambda)|{\rm div} u|^2\,dx\,dt=\int_{\mathbb{T}^3}\frac{\rho_0^{\gamma}}{\gamma-1}\,dx$$
Moreover, the scaled kinetic energy vanishes in the limit: for every fixed $t>0$,
\[
\varepsilon \int_{\mathbb{T}^3} \rho^\varepsilon(t,x)\, \lvert u^\varepsilon(t,x)\rvert^2 \, dx
\longrightarrow 0
\quad \text{as } \varepsilon \to 0.
\]

\label{prop of weak solution}
For any $\varepsilon>0$, there exists a subsequence of $(\rho_{\varepsilon},u_{\varepsilon})$ such that 
\begin{equation*}
\begin{split}
\label{convergence from energy}
&\rho_{\varepsilon}\to \rho \text{ in } C(0,T;L^{\gamma}_{weak}(\mathbb{T}^3)),\;\;\; \rho_{\varepsilon}\to \rho \text{ in } L^1(0,T;L^1(\mathbb{T}^3)),
\\&u_{\varepsilon}\to u \text{ weakly in } L^2(0,T;W^{1,2}(\mathbb{T}^3)),
\end{split}
\end{equation*}
and the weak limit $(\rho,u)$ is a weak solution to \eqref{system of limit}-\eqref{initial data for limit system}.

With uniform bounds \eqref{uniform bounds from energy1}, \eqref{uniform bounds from energy2} and \eqref{uniform bounds from energy3}, and Lemma \ref {effective 1} at hands, we deduce that 
\begin{equation}
\begin{split}
\label{convergence from energy}
&\rho_{\varepsilon}\to \rho \text{ in } C(0,T;L^{\gamma}_{weak}(\mathbb{T}^3)),
\\&u_{\varepsilon}\to u \text{ weakly in } L^2(0,T;W^{1,2}(\mathbb{T}^3)),
\end{split}
\end{equation}

By Lemma \ref{effective 1},  we have 
\begin{equation}
\label{convergence of pressure}
\rho_{\varepsilon}^{\gamma}\to \bar{\rho^{\gamma}} \text{ weakly in } L^{\frac{\gamma+\theta}{\gamma}}((0,T)\times\mathbb{T}^3),
\end{equation}
where $\bar{f}$ is the weak limit of the sequence $\{f_n\}$.

For any $\gamma>\frac{3}{2}$,  and \eqref{convergence from energy} yields  
$$\rho_{\varepsilon}u_{\varepsilon}\to \rho u\text{ in}\;\;  D'((0,T)\times\mathbb{T}^3).$$

Note that 
\begin{equation*}
\begin{split}
\|\varepsilon\rho_{\varepsilon}u_{\varepsilon}\|_{L^{\infty}(0,T;L^{\frac{2\gamma}{\gamma+1}}(\mathbb{T}^3))}&\leq \sqrt{\varepsilon}\|\sqrt{\varepsilon\rho_{\varepsilon}}u_{\varepsilon}\|_{L^{\infty}(0,T;L^2(\mathbb{T}^3))}\|\sqrt{\rho_{\varepsilon}}\|_{L^{\infty}(0,T;L^{2\gamma}(\mathbb{T}^3))}
\\&\to 0 \quad\text{ as } \varepsilon \to 0,
\end{split}
\end{equation*}
thus we have $\varepsilon \rho_{\varepsilon}u_{\varepsilon}\to 0\text{ in } L^{\infty}(0,T;L^{\frac{2\gamma}{\gamma+1}}(\mathbb{T}^3)).$

With the help of  \eqref{convergence from energy},  this can ensure that 
$$\varepsilon\rho_{\varepsilon}u_{\varepsilon}\otimes u_{\varepsilon}\to 0 \text{ in }\;D'((0,T)\times\mathbb{T}^3)$$
for any $\gamma> \frac{3}{2}$.

Thus,  letting $\varepsilon\to 0$, we are able to recover the weak limit  $(\rho, u)$ of the sequence of solutions $(\rho_{\varepsilon},u_{\varepsilon})$. In particular, this weak limit  satisfies 
 \begin{equation}
\label{weak limit of system}
\begin{cases}
\partial_t \rho + {\rm div}(\rho u) = 0, \\[6pt]
\nabla \bar{\rho^{\gamma}} = \nu\Delta u + (\nu + \lambda)\nabla({\rm div} u),
\end{cases}
\end{equation}
in the sense of $D'((0,T)\times\mathbb{T}^3).$  To show this weak limit is a weak solution to the equation, 
we still need to show that 
\[
\rho^{\gamma} = \overline{\rho^{\gamma}} .
\]
This follows from the strong convergence of the density in $L^1(0,T;L^1(\mathbb{T}^3))$.
The strong convergence of the density relies on uniform bounds and the weak continuity of the effective flux.
The proof closely follows the argument in Section~4 of \cite{FNP}.
Meanwhile, we can deduce the following energy inequality
\begin{equation}
\label{energy inequality for limit system}
\int_{\mathbb{T}^3}\frac{\rho^{\gamma}}{\gamma-1}\,dx+\int_0^T\int_{\mathbb{T}^3}\nu |\nabla u|^2+(\nu+\lambda)|{\rm div} u|^2\,dx\,dt\leq\int_{\mathbb{T}^3}\frac{\rho_0^{\gamma}}{\gamma-1}\,dx.
\end{equation}

\label{Propo for energy}
Let $(\rho,u)$ be any weak solution to \eqref{system of limit}--\eqref{initial data for limit system}
satisfying the energy inequality \eqref{energy inequality for limit system}. Then the following energy equality
\begin{equation}
\label{energy equality}
\int_{\mathbb{T}^3}\frac{\rho^{\gamma}}{\gamma-1}\,dx+\int_0^T\int_{\mathbb{T}^3}\nu |\nabla u|^2+(\nu+\lambda)|{\rm div} u|^2\,dx\,dt=\int_{\mathbb{T}^3}\frac{\rho_0^{\gamma}}{\gamma-1}\,dx
\end{equation}
holds.
